export function createCanvas(width: number, height: number): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  return canvas;
}

export function render(canvas: HTMLCanvasElement, ctx: CanvasRenderingContext2D, state: { player: { x: number; y: number }; enemies: { x: number; y: number }[]; cheese: { x: number; y: number } }) {
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  ctx.arc(state.cheese.x, state.cheese.y, 10, 0, Math.PI * 2);
  ctx.fill();
  state.enemies.forEach((enemy) => {
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, 10, 0, Math.PI * 2);
    ctx.fill();
  });
  ctx.beginPath();
  ctx.arc(state.player.x, state.player.y, 10, 0, Math.PI * 2);
  ctx.fill();
}

export function getKeyDown(key: string): boolean {
  const keys = Object.keys(window.__keyStates || {});
  return keys.includes(key.toLowerCase());
}

export class Scene {
  private entities: { update: (dt: number) => void; render: () => void }[] = [];

  constructor(private canvas: HTMLCanvasElement) {
    this.canvas = canvas;
    this.canvas.width = 800;
    this.canvas.height = 600;
  }

  addEntity(entity: { update: (dt: number) => void; render: () => void }) {
    this.entities.push(entity);
  }

  update(dt: number) {
    this.entities.forEach((e) => e.update(dt));
  }

  render() {
    const ctx = this.canvas.getContext('2d');
    if (!ctx) return;
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);
    this.entities.forEach((e) => e.render());
  }
}

export class Cheese {
  position: { x: number; y: number; z: number };
  velocity: { x: number; y: number; z: number };
  constructor(x: number, y: number, z: number) {
    this.position = { x, y, z };
    this.velocity = { x: 0, y: 0, z: 0 };
  }
  update(dt: number) {
    this.velocity.y -= 0.05 * dt;
    this.position.x += this.velocity.x * dt;
    this.position.y += this.velocity.y * dt;
    this.position.z += this.velocity.z * dt;
  }
  render(renderer: any) {
    renderer.renderCheese(this.position);
  }
}

export class Enemy {
  position: { x: number; y: number };
  velocity: { x: number; y: number };
  target: { x: number; y: number };
  speed: number;

  constructor() {
    this.position = { x: 0, y: 0 };
    this.velocity = { x: 0, y: 0 };
    this.target = { x: 0, y: 0 };
    this.speed = 0.5;
  }

  update(playerPosition: { x: number; y: number }) {
    this.target = playerPosition;
    const dx = this.target.x - this.position.x;
    const dy = this.target.y - this.position.y;
    const distance = Math.hypot(dx, dy);
    this.velocity = { x: dx / distance * this.speed, y: dy / distance * this.speed };
    this.position.x += this.velocity.x;
    this.position.y += this.velocity.y;
  }

  render(canvasContext: CanvasRenderingContext2D) {
    canvasContext.fillStyle = 'red';
    canvasContext.fillRect(this.position.x, this.position.y, 20, 20);
  }
}

export class Item {
  private position: { x: number; y: number; z: number };
  private scale: { x: number; y: number; z: number };
  private color: string;
  private picked: boolean;

  constructor(x: number, y: number, z: number) {
    this.position = { x, y, z };
    this.scale = { x: 0.5, y: 0.5, z: 0.5 };
    this.color = '#ffd700';
    this.picked = false;
  }

  public update(dt: number) {}

  public render(renderer: import('three').Renderer) {
    const geometry = new import('three').SphereGeometry(this.scale.x, this.scale.y, this.scale.z);
    const material = new import('three').MeshBasicMaterial({ color: this.color });
    const mesh = new import('three').Mesh(geometry, material);
    mesh.position.set(this.position.x, this.position.y, this.position.z);
    renderer.scene.add(mesh);
  }

  public onPick() {
    this.picked = true;
  }

  public isPicked() {
    return this.picked;
  }
}

