// Chess piece definitions
const pieces = {
  'king': '♔',
  'queen': '♕',
  'rook': '♖',
  'bishop': '♗',
  'knight': '♘',
  'pawn': '♙'
};

// Chess board definition
const board = Array.from({ length: 12 }, () => Array(12).fill(null));

// Function to initialize the board
function initBoard() {
  // Place pawns
  for (let i = 2; i < 10; i++) {
    for (let j = 0; j < 12; j++) {
      board[i][j] = 'pawn';
    }
  }

  // Place rooks
  board[0][0] = 'rook';
  board[0][11] = 'rook';
  board[11][0] = 'rook';
  board[11][11] = 'rook';

  // Place knights
  board[0][1] = 'knight';
  board[0][10] = 'knight';
  board[11][1] = 'knight';
  board[11][10] = 'knight';

