export function run() {
  const args = process.argv.slice(2);

  if (args.length < 3) {
    console.error('Usage: node main.js <amount> <totalPeople> <equal|percentage>');
    process.exit(1);
  }

  const amount = parseFloat(args[0]);
  const totalPeople = parseInt(args[1], 10);
  const method = args[2];

  if (isNaN(amount) || isNaN(totalPeople) || totalPeople <= 0) {
    console.error('Invalid input. Amount must be a number and totalPeople must be a positive integer.');
    process.exit(1);
  }

  const result = splitExpense(amount, totalPeople, method);
  if (result) {
    console.log(`Expense split successfully.`);
    console.log(`Each person pays: ${result}`);
  } else {
    console.error(`Failed to split expense.`);
  }
}

export function main() {
  run();
}

export interface BudgetItem {
  id: number;
  name: string;
  amount: number;
  payer: string;
  recipients: string[];
}

export function splitExpense(amount: number, totalPeople: number, method: string): number {
  if (method === 'equal') {
    return amount / totalPeople;
  }
  return amount;
}

export function calculateOwes(budgetItems: BudgetItem[]): Record<string, number> {
  const owes: Record<string, number> = {};

  for (const item of budgetItems) {
    for (const recipient of item.recipients) {
      if (recipient !== item.payer) {
        owes[item.payer] = (owes[item.payer] || 0) + item.amount;
        owes[recipient] = (owes[recipient] || 0) - item.amount;
      }
    }
  }

  return owes;
}

import { BudgetItem } from './budget';

export async function loadBudget(filePath: string): Promise<BudgetItem[]> {
  try {
    const data = await Deno.readTextFile(filePath);
    const items = JSON.parse(data) as BudgetItem[];
    return items;
  } catch (error) {
    console.error(`Error loading budget from ${filePath}: ${error.message}`);
    return [];
