        int a = 0, b = 1;
        var buffer = new System.Text.StringBuilder();
        for (int i = 0; i < length; i++)
        {
            buffer.Append(a);
            a += b;
            b = a - b;
            if (i < length - 1) buffer.Append(", ");
        }
        return buffer.ToString();
    }
