void reverseString(std::string& str) {
    int n = str.length();
    for (int i = 0; i < n / 2; ++i) {
        std::swap(str[i], str[n - i - 1]);
    }
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: ./reverse <string>" << std::endl;
        return 1;
    }
    std::string input = argv[1];
    reverseString(input);
    std::cout << input << std::endl;
    return 0;
}

