// Reverses a null-terminated C string `s` in place
void reverseString(char *s) {
  if (s == NULL || *s == '\0') return;
  size_t len = strlen(s);
  for (size_t i = 0; i < len / 2; ++i) {
    char tmp = s[i];
    s[i] = s[len - i - 1];
    s[len - i - 1] = tmp;
  }
}

