            if (count == 0)
            {
                Console.WriteLine("No valid numbers to average.");
            }
            else
            {
                double average = sum / count;
                Console.WriteLine($"Average: {average}");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}

