import { Note } from '../types';

const notes: Note[] = [];

export const createNote = (note: Note): Note => {
  const newNote = { ...note, id: Date.now().toString() };
  notes.push(newNote);
  return newNote;
};

export const getNotes = (): Note[] => {
  return notes;
};

export const updateNote = (id: string, updatedNote: Note): Note | undefined => {
  const index = notes.findIndex(note => note.id === id);
  if (index !== -1) {
    notes[index] = { ...updatedNote, id };
    return notes[index];
  }
  return undefined;
};

export const deleteNote = (id: string): void => {
  const index = notes.findIndex(note => note.id === id);
  if (index !== -1) {
    notes.splice(index, 1);
  }
};

import express from 'express';
import { createNote, getNotes, updateNote, deleteNote } from '../services/noteService';
import { Note } from '../types';

const noteRouter = express.Router();

noteRouter.get('/', (req, res) => {
  const notes = getNotes();
  res.json(notes);
});

noteRouter.post('/', (req, res) => {
  const note: Note = req.body;
  const newNote = createNote(note);
  res.status(201).json(newNote);
});

noteRouter.put('/:id', (req, res) => {
  const id = req.params.id;
  const updatedNote: Note = req.body;
  const result = updateNote(id, updatedNote);
  if (result) {
    res.json(result);
  } else {
    res.status(404).send('Note not found');
  }
});

noteRouter.delete('/:id', (req, res) => {
  const id = req.params.id;
  deleteNote(id);
  res.status(204).send();
});

export { noteRouter };

export interface Note {
  id: string;
  title: string;
  content: string;
}

import React, { useState, useEffect } from 'react';
import { fetchNotes, addNote, updateNote, deleteNote } from './api/notes';

type Note = {
  id: string;
  content: string;
};

class App extends React.Component {
  state = {
    notes: [] as Note[],
    newNote: '',
    editingNote: { id: '', content: '' } as Note,
  };

  componentDidMount() {
    fetchNotes().then(notes => this.setState({ notes }));
  }

  handleAdd = () => {
    const { newNote } = this.state;
    if (newNote.trim()) {
      addNote(newNote).then(notes => this.setState({ notes, newNote: '' }));
    }
  };

  handleEdit = (id: string, content: string) => {
    this.setState({ editingNote: { id, content } });
  };

  handleUpdate = () => {
    const { editingNote } = this.state;
    if (editingNote.id && editingNote.content.trim()) {
      updateNote(editingNote.id, editingNote.content).then(notes => this.setState({ notes, editingNote: { id: '', content: '' } }));
    }
  };

  handleDelete = (id: string) => {
    deleteNote(id).then(notes => this.setState({ notes }));
  };

  render() {
    const { notes, newNote, editingNote } = this.state;
    return (
      <div>
        <h1>Notes</h1>
        <input
          type='text'
          value={newNote}
          onChange={(e) => this.setState({ newNote: e.target.value })}
          placeholder='Add a new note'
        />
        <button onClick={this.handleAdd}>Add</button>
        {editingNote.id && (
          <div>
            <input
              type='text'
              value={editingNote.content}
              onChange={(e) => this.setState({ editingNote: { ...editingNote, content: e.target.value } })}
              placeholder='Edit note'
            />
            <button onClick={this.handleUpdate}>Update</button>
          </div>
        )}
        <ul>
          {notes.map(note => (
            <li key={note.id}>
              {note.content}
              <button onClick={() => this.handleEdit(note.id, note.content)}>Edit</button>
              <button onClick={() => this.handleDelete(note.id)}>Delete</button>
            </li>
          ))}
        </ul>
      </div>
    );
  }
}

export default App;

