export interface Note {
  id: number;
  content: string;
}

let notes: Note[] = [];

export default notes;

import notes from '../data/notes';
import { Note } from '../data/notes';

let nextId = 1;

export const getAllNotes = (): Note[] => {
  return notes;
};

export const addNote = (content: string): Note => {
  const newNote: Note = { id: nextId++, content };
  notes.push(newNote);
  return newNote;
};

export const updateNote = (id: number, content: string): Note | null => {
  const note = notes.find(n => n.id === id);
  if (note) {
    note.content = content;
  }
  return note || null;
};

export const deleteNote = (id: number): boolean => {
  const index = notes.findIndex(n => n.id === id);
  if (index !== -1) {
    notes.splice(index, 1);
    return true;
  }
  return false;
};

import express from 'express';
import { getAllNotes, addNote, updateNote, deleteNote } from '../services/notes';

const notesRouter = express.Router();

notesRouter.get('/', (req, res) => {
  res.json(getAllNotes());
});

notesRouter.post('/', (req, res) => {
  const { content } = req.body;
  const newNote = addNote(content);
  res.status(201).json(newNote);
});

notesRouter.put('/:id', (req, res) => {
  const { id } = req.params;
  const { content } = req.body;
  const note = updateNote(Number(id), content);
  if (note) {
    res.json(note);
  } else {
    res.status(404).send('Note not found');
  }
});

notesRouter.delete('/:id', (req, res) => {
  const { id } = req.params;
  const deleted = deleteNote(Number(id));
  if (deleted) {
    res.status(204).send();
  } else {
    res.status(404).send('Note not found');
  }
});

