    const note = createNote(sampleNote);
    expect(note.title).toBe('Test');
    expect(note.content).toBe('This is a test note.');
  });

  it('should get notes', () => {
    const notes = getNotes();
    expect(Array.isArray(notes)).toBe(true);
  });

  it('should update a note', () => {
