export interface Note {
  id: string;
  title: string;
  content: string;
  createdAt: Date;
}

export class NotesService {
  private notes: Note[];

  constructor() {
    this.notes = [];
  }

  createNote(title: string, content: string): Note {
    const newNote: Note = {
      id: generateId(),
      title,
      content,
      createdAt: new Date(),
    };
    this.notes.push(newNote);
    return newNote;
  }

  getNotes(): Note[] {
    return this.notes;
  }

  updateNote(id: string, title: string, content: string): Note | null {
    const noteIndex = this.notes.findIndex(n => n.id === id);
    if (noteIndex === -1) return null;
    this.notes[noteIndex].title = title;
    this.notes[noteIndex].content = content;
    return this.notes[noteIndex];
  }

  deleteNote(id: string): void {
    this.notes = this.notes.filter(n => n.id !== id);
  }
}

function generateId(): string {
  return Math.random().toString(36).substr(2, 9);
}

import { NotesService } from './notes';

export function startServer() {
  const notesService = new NotesService();
  console.log('Notes server started');
}

import { NotesService, Note } from './notes';

export function routes() {
  const notesService = new NotesService();
  return {
    '/notes/create': {
      method: 'POST',
      handler: (req, res) => {
        const { title, content } = req.body;
        const note = notesService.createNote(title, content);
        res.send({ note });
      }
    },
    '/notes/:id': {
      method: 'GET',
      handler: (req, res) => {
        const note = notesService.getNotes().find(n => n.id === req.params.id);
        if (note) {
          res.send({ note });
        } else {
          res.status(404).send({ error: 'Note not found' });
        }
      }
    },
    '/notes': {
      method: 'GET',
      handler: (req, res) => {
        const notes = notesService.getNotes();
        res.send({ notes });
      }
    },
    '/notes/:id/update': {
      method: 'PUT',
      handler: (req, res) => {
        const { title, content } = req.body;
        const note = notesService.updateNote(req.params.id, title, content);
        if (note) {
          res.send({ note });
        } else {
          res.status(404).send({ error: 'Note not found' });
        }
      }
    },
