package main

import (
	"flag"
	"fmt"
	"log"
	"os"
	"path/filepath"
)

var maxFiles = 10

type fileInfo struct {
	path  string
	size  int64
}

func (f fileInfo) String() string {
	return fmt.Sprintf("%s: %d bytes", f.path, f.size)
}

func main() {
	dir := os.Getenv("PWD")
	if dir == "" || dir == "/" {
		log.Fatal("could not find working directory")
	}

	flags := flag.NewFlagSet("", flag.ContinueOnError)
	var quiet bool
	flags.BoolVar(&quiet, "quiet", false, "squelch all log output and only print results")
	flags.Parse(os.Args[1:])
	if !quiet {
		fmt.Printf("walking directory tree from %s\n", dir)
	}

	// walk the entire directory and find all files
	var w walker
	err := filepath.WalkDir(dir, func(pa string, d os.DirEntry, err error) error {
		if err != nil {
			return fmt.Errorf("skipping path: %w", err)
		}
		if !d.Type().IsRegular() || pa == dir {
			return nil // skip non-regular files and base directory itself
		}

		sizeInfo := fileInfo{path: pa, size: d.Size()}
		w.record(sizeInfo)

		return nil
	})

	if err != nil {
		log.Fatalf("failed walking directory tree from %s: %v", dir, err)
	}

	for i, f := range w.topTen() {
		fmt.Printf("%s\n", f)
		 //fmt.Printf("#%d\t%s\t%d bytes\n", 1+i, fi.Path+"/"+n, sz.Size())
	}

	fmt.Printf("done. processed %d files total.\n", len(w.bySize))

	exitErr := flags.Args()
	if len(exitErr) > 0 {
		os.Exit(2)
	}
}

type walker struct {
	// bySize is the full slice of all sizes we've seen so far.
	// The top-10 largest are kept in front via bubbleSortBySize.
	bySize []fileInfo
}

func (w *walker) record(fi fileInfo) {
	w.bySize = append(w.bySize, fi)
	sortByWeight(&w.bySize)
	if len(w.bySize) > maxFiles && w.bySize[maxFiles-1].size < w.bySize[len(w.bySize)-1].size {
		bubbleShift(&w.bySize, len(w.bySize)-1)
	}
}

func (w *walker) topTen() []fileInfo {
	copyOut := make([]fileInfo, maxFiles)
	copy(copyOut[:], w.bySize[:])
	return copyOut
}

// bubbleSortByWeight sorts the heap in ascending order by size.
func sortByWeight(heap *[maxFiles]interface{}) {
	n := len(*heap)
	for i := n/2 - 1; i >= 0; i-- {
		bubbleShift(heap, i)
	}
}

// bubbleShift moves the element at index x and fixes up.
func bubbleShift(heap *[maxFiles]interface{}, parent int) {
	sizeOfParent := heap[parent].(_type).Size()
	child := parent<<1 + 1
	for child < len(*heap) && sizeOfChild((*heap)[child].(_type)) < sizeOfChild((*heap)[child+1].(_type))) {
		child++
	}

	if child >= len(heap) || sizeOfParent >= sizeOfChild((*heap)[child].(_type).Size()) {
		return
	}

	swap(heap, parent, child)
	bubbleShift(heap, parent)
}

func swap(heap *[maxFiles]interface{}, a int, b int) { heap[a], heap[b] = heap[b], heap[a] }

