	"a-go-command-line-utility-that-prints-the-size-of-every-file-in-a-directory/internal/fileservice"
)

func main() {
	if len(os.Args) != 2 {
		fmt.Println("Usage: printsizes <directory>")
		os.Exit(1)
	}

	dir := os.Args[1]
	fileSizeReport, err := fileservice.ListFiles(dir)
	if os.IsNotExist(err) {
		fmt.Printf("Directory '%s' does not exist.\n", dir)
		return
	}
	if err != nil {
		fmt.Println("Error reading directory:", err.Error())
		os.Exit(1)
	}

	for _, fileData := range fileSizeReport.Files {
		fmt.Printf("%s - Size: %d bytes\n", fileData.Name, fileData.SizeBytes)
	}

	totalSize := fileservice.SumFileSizes(fileSizeReport.Files)
	if totalSize == 0 {
		fmt.Println("Total size of all files:", totalSize, "bytes")
		return
	}
	fmt.Printf("There are %d files in '%s' directory. Total size: %d bytes\n", len(fileSizeReport.Files), dir, totalSize)
}

