interface MarkdownFile {
  path: string;
  content: string;
}

interface ParsedMarkdown {
  title: string;
  date: string;
  tags: string[];
  body: string;
}

export function parseMarkdown(file: MarkdownFile): ParsedMarkdown {
  const lines = file.content.split('\n');
  let title = '';
  let date = '';
  let tags: string[] = [];
  let body = '';

  let inHeader = true;
  for (const line of lines) {
    if (inHeader) {
      if (line.startsWith('title: ')) {
        title = line.slice(7);
      } else if (line.startsWith('date: ')) {
        date = line.slice(6);
      } else if (line.startsWith('tags: ')) {
        tags = line.slice(6).split(',').map(t => t.trim());
      } else if (line === '') {
        inHeader = false;
      }
    } else {
      body += line + '\n';
    }
  }

  return { title, date, tags, body };
}

export function renderHtml(title: string, content: string, date: string, author: string): string {
  return `
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${title}</title>
  <style>
    body { font-family: Arial, sans-serif; margin: 20px; }
    h1 { color: #333; }
    .metadata { color: #777; font-size: 0.9em; margin-bottom: 10px; }
    .content { line-height: 1.6; }
  </style>
</head>
<body>
  <h1>${title}</h1>
  <div class="metadata">Published on ${date} by ${author}</div>
  <div class="content">${content}</div>
</body>
</html>
`;
}

