import { addMeeting, listMeetings, checkOverlap } from './scheduler';

export function run() {
  console.log('Meeting Scheduler started. Use `add` to schedule and `list` to view meetings.');
}

export function main() {
  run();
}

main();

export interface Meeting {
  id: number;
  title: string;
  startTime: Date;
  endTime: Date;
}

let meetings: Meeting[] = [];

export function addMeeting(title: string, startTime: Date, endTime: Date): void {
  if (checkOverlap(startTime, endTime)) {
    console.error('Meeting overlaps with existing meetings.');
    return;
  }
  meetings.push({ id: Date.now(), title, startTime, endTime });
}

export function listMeetings(): Meeting[] {
  return meetings;
}

export function checkOverlap(startTime: Date, endTime: Date): boolean {
  for (const meeting of meetings) {
    if (startTime < meeting.endTime && endTime > meeting.startTime) {
      return true;
    }
  }
  return false;
}

import { Meeting } from './scheduler';

export function loadMeetings(): Meeting[] {
  try {
    const data = require('../data/meetings.json');
    return data || [];
  } catch {
    return [];
  }
}

export function saveMeetings(meetings: Meeting[]): void {
  try {
    require('fs').writeFileSync('../data/meetings.json', JSON.stringify(meetings, null, 2));
  } catch (e) {
    console.error('Failed to save meetings:', e);
  }
}

