namespace Storage {
    public class StorageLayerService {
        private List<Contact> _contacts;

        public StorageLayerService() {
            // Initialize with a fixed list of contacts (later you can replace this with a static file path)
            const string filePath = "../../../src/Storage/contact.json";
            if (!File.Exists(filePath)) {
                var sampleContacts = new List<Contact>() {
                    new Contact { Name = "Alice Smith", Email = "alice@example.com" },
                    new Contact { Name = "Bob Ross", Email = "bob@artsy.net" }
                };
                File.WriteAllTextAsync(filePath, System.Text.Json JsonSerializer.Serialize(sampleContacts)).Wait();
            }
            _contacts = LoadFromFile(filePath);
        }

        private List<Contact> LoadFromFile(string filePath) {
            string jsonFileContent;
            try { 
                jsonFileContent = File.ReadAllText(filePath); 
            } catch (Exception e) { 
                Console.Error.WriteLine($"Failed to read file: '{filePath}'. Error:'{e.Message}'");
                return new List<Contact>();  
            }

            try {
                var contacts = System.Text.Json.JsonSerializer.Deserialize<List<Contact>>(jsonFileContent, 
                    new System.Text.Json.JsonSerializerOptions() { PropertyNameCaseInsensitive = true });

                if (contacts == null) { Console.WriteLine("Contacts file is missing or corrupted. Assuming empty list."); return new List<Contact>(); }
                return contacts;
            } catch {
                // If something goes boom in the JSON parsing, we're still okay and returning an empty list works pretty well. 
                // But you might want to log a helpful message (or even try again with some default data).
                Console.WriteLine($"Failed to deserialize '{filePath}' contents; assuming empty contact set.");
                return new List<Contact>();  
            }
        }

        public void AddContact(Contact contact) {
            _contacts.Add(contact);
            string json = System.Text.Json.JsonSerializer.Serialize(_contacts);
            File.WriteAllTextAsync(LoadContactsFile(), json).Wait(); // Assuming contacts file is already checked earlier.
        }

        // This method doesn't modify the storage state — it only does a simple query based on provided input and returns results.
        public List<Contact> SearchContacts(string keyword) { 
              var matches = (from contact in _contacts where contact.Name.Contains(keyword, StringComparison.OrdinalIgnoreCase)
                             select contact).ToList();

              return matches.Count > 0 ? matches : new List<Contact>();
         }

        // This method is slightly smarter than the 'add', since it's aware of the current full collection and
        // sorts the output list by name (ascending order) after checking for existence. 
        public List<Contact> ListAllContactsSorted() {
            var sortedAndUnique = _contacts.GroupBy(contact => contact.Email)
                                          .Select(g => g.First())  // Taking one from each group to avoid duplicates.
                                          .OrderByDescending(c => c.Name.Length)  // Assuming you want name order by length descending (not exact alpha).
                                          .ToList();
          return sortedAndUnique.Count > 0 ? sortedAndUnique : new List<Contact>();
        }

        private string LoadContactsFile() {
            const string dir = "../../../src/Storage/";
            try { Directory.CreateDirectory(dir); } catch {}
            return Path.Combine(dir, "contact.json");
        }
    }
}

