import java.io.IOException;
import java.util.List;

public class AddTaskCommand {
    private static final String TASK_FILE_PATH = "tasks.txt";

    /**
     * Adds a new task to the data store.
     */
    public boolean executeAddTask(final String description) throws IOException {
        // Read existing tasks from file
        List<String> currentTasks;
        try {
            currentTasks = readFromFile();
        } catch (IOException e) {
            System.out.println("Failed while reading tasks. Error: " + e.getMessage());
            return false;
        }

        // Add new task to the end of the list
        currentTasks.add(description);

        // Write updated list back to file
        writeToFile(currentTasks);

        System.out.println("Task added successfully.");

        return true;    
    }

    // This method writes all tasks into 'tasks.txt'
    private static List<String> readFromFile() throws IOException {
        final var bufferedReader = new java.io.BufferedReader(new java.io.FileReader(TASK_FILE_PATH));
        try {
            final List<String> taskList = bufferedReader.lines().toList();
            return taskList;
        } finally { 
            if (bufferedReader != null) bufferedReader.close();    
        }
    }

    // Write list of strings as a line per string in file path.
    private static void writeToFile(final List<String> tasks) throws IOException {
        final var fileWriter = new java.io.PrintWriter(new java.io.File(TASK_FILE_PATH));

        try { 
            for (String task : tasks) { 
                fileWriter.println(task); 
            }
            // Writing and flushing is already handled by PrintWriter so no need to manually flush() or close().
        } catch(final Exception e) {
             System.out.println("Failed to write new tasks. Error: " + e.getMessage());
        }
    }
}

