func addNote() error {
	scanner := bufio.NewScanner(os.Stdin)

	var title, category, content string
	fmt.Print("\nEnter Title of Note: ")
	scanner.Scan()
	title = scanner.Text()

	fmt.Print("Enter Category (optional): ")
	scanner.Scan()
	category = scanner.Text()

	fmt.Println("-- Please type the full note below. --")
	for _, line := range readInputUntilEmpty(scanner) {
		content += line + "\n"
	}
	if content == "" {
		return fmt.Errorf("[note add] Nothing written: empty notes don't make sense.")
	}

	notesFile, err := os.Open("notes.json", os.O_RDWR|os.O_CREATE, 0644)
	if err != nil {
		return err
	}
	defer notesFile.Close()

	var all []Note
	err = json.Unmarshal(notesFile.ReadAll(), &all)
	if err != nil && !errors.Is(err, io.EOF) {
		return fmt.Errorf("[note add] %d existing notes: %w", len(all), err)
	}

	n := Note{Title: title, Category: category, Content: content}
	all = append(all, n)

	err = json.NewEncoder(notesFile).Encode(&all)
	if err != nil {
		return err
	}
	fmt.Printf("✓ Noted '%s' into category '%s'\n", title, categoryOrDefault(category))
}

func listNotes() error {
	notesFile, _ := os.Open("notes.json")
	defer notesFile.Close()

	var all []Note
	err := json.Unmarshal(notesFile.ReadAll(), &all)
	if err != nil && !errors.Is(err, io.EOF) {
		fmt.Println("[note list] No existing notes.\nYou can add a new one right now.")
