package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"

	jsonstorage "a-multi-file-go-cli-note-manager-with-add-list-and-search-subcommands-that-stores-notes-in-a-json-file/cmd/storage/json"
)

func AddNoteArgumentParser(args []string) (message string, err error) {
	if len(args) < 1 || args[0] == "-h" || args[0] == "--help" {
		fmt.Println("Usage: add_note <note>")
		return "", nil
	}
	message = strings.Join(args[1:], " ")
	return message, nil
}

func main() {
	var args = os.Args
	if len(args) < 2 {
		fmt.Println("Usage: go run ./src [command]... [options]")
		os.Exit(1)
	}

	switch args[1] {
	case "add":
		noteMessage, err := AddNoteArgumentParser(args[2:len(args)])
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing add arguments: %v\n", err)
			os.Exit(1)
		}
		jsonstorage.SaveNotes([]jsonstorage.Note{{
			Title:  noteMessage,
			Timestamp: 0,
		}})
		fmt.Println("Note saved successfully")

	case "list":
		listNotes(args[2:len(args)])

	case "search":
		searchQuery, err := AddNoteArgumentParser(args[3:])
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing search arguments: %v\n", err)
			os.Exit(1)
		}
		matchedNotes, _ := jsonstorage.LoadNotes()
		filters, err := parseSearchArgs(searchQuery, matchedNotes)
		if filters == nil || err != nil {
			fmt.Printf("Failed to load notes. Error: %v\n", err)
			return
		}

		matchedFiltered := searchNoteByFilter(filters, matchedNotes)
		json.NewEncoder(os.Stdout).SetIndent("", "\t")
		err = json.NewEncoder(os.Stdout).Encode(matchedFiltered)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Failed to encode found notes: %v", err)
		}

	default:
		fmt.Println("Unknown command:", args[1])
	}
}

func parseSearchArgs(query string, notes []jsonstorage.Note) (map[string]*jsonstorage.FilterOption, error) {
	var filters = map[string]*jsonstorage.FilterOption{}
	for _, s := range strings.Split(strings.TrimPrefix(query, "--"), " ") {
		filters[strings.TrimSpace(s)] = newFilterOptions()
	}
	return filters, nil
}

func parseSearchArg(arg string, notes []jsonstorage.Note) (*jsonstorage.FilterOption, error) {
	var filter *jsonstorage.FilterOption

	if len(arg) <= 2 || strings.HasPrefix(arg, "--") { // Filter arg parsing
		for _, s := range strings.Split(strings.TrimPrefix(arg, "--"), " ") {
			filter, _ = parseSearchArg(s, notes)
		}
		return filter, nil
	}

	noteCount := countFilters(notes)

	switch noteCount {
	case 1:
		sFilter := new(jsonstorage.FilterOption)
		filters := strings.Fields(sFilter.FilterString)
		for _, f := range filters[2:] { // skip FilterString "Title:" and ":Body"
			if f == "" {
				continue
			}
			filter = &jsonstorage.FilterOption{
				Type:           strings.TrimSpace(filters[1]),
				Term:           strings.TrimSpace(f),
				MatchSubstrings: false,
			}
			for _, o := range filter.OperandTypes() { // e.g. "T:" or ":B"
				if contains(notes, sFilter.Title, noteCount) && strings.HasPrefix(f, "T:") {
					f = f[2:]
				} else if contains(notes, sFilter.Body, noteCount) && strings.HasPrefix(f, ":B") { // :B will match Body as well
					f = f[3:]
				}
			}

			if filter.Term != "" {
				filters := newFilters(sFilter.FilterString)
				switch filters.Type {
				case "T:":
					filter.Terms.Title = append(filter.Terms.Title, string(f))
				default: // :B
					filter.Terms.Body = append(filter.Terms.Body, string(f))
				}
			}

			return filter, nil
		}

	default:

		for _, s := range strings.Split(arg) {
			noteCount := countFilters(s)
			if noteCount == 1 { // Single value arg parsing
				sFilter := new(jsonstorage.FilterOption)
				filters := strings.Fields(sFilter.FilterString)

				strVal, _ := sFilter.Value(filters[2])
				if strToVal(strVal) {
					filter = &jsonstorage.FilterOption{Type: "", Term: "Not Found", MatchSubstrings: false}
					return filter, nil
				}

				if filters[0] == "" || strings.HasPrefix(s, "--") { // Filter arg parsing; s is a Filter option
					f, _ := parseSearchArg(sFilter.FilterString[2:], notes)
					filter = f
					return f, nil

				} else {
					for _, filterOption := range filters {
						switch s := filterOption; s { case "T:":
							sFilter.Title = append(sFilter.Title, noteCount-1)
						case ":B": // :B will match Body as well
							sFilter.Body = append(sFilter.Body, noteCount-1)

						default: // single value
							strVal := strToVal(filterOption[2:])
							if isNumber(strVal) && !strings.HasPrefix(filterOption[3:], "B") {
								err := sFilter.SetTimestamp(&strVal)
								f := &jsonstorage.FilterOption{
									Term: strings.TrimSpace(s),
									Type: "",
									MatchSubstrings: false,
								}
								return f, err
							case ":T":
								sFilter.Title = append(sFilter.Title, noteCount-1) // Single value arg parsing; :B will match Title as well

						default:
							continue
						}

					} filter = &jsonstorage.FilterOption{Type: "Invalid", Term: "", MatchSubstrings: false}
				}
			}
		}

		noteCount := countFilters(query)
		sFilter := new(jsonstorage.FilterOption)

		if noteCount == 1 {
			filters, _ := parseSearchArg(query[2:], notes) // Filter arg parsing
			return filters, nil

		} else { // Multiple value args; Filter option argument
			var filter *jsonstorage.FilterOption
			for _, s := range strings.Fields(query) {
				if strings.HasPrefix(s, "--") && len(strings.TrimSpace(s)) > 2 || len(strings.TrimSpace(s)) == 0 {
					continue
				}

				sFilter.Clear()
				filters := strings.Fields(s)

