)

func AddNoteArgumentParser(args []string) (message string, err error) {
	if len(args) < 1 || args[0] == "-h" || args[0] == "--help" {
		fmt.Println("Usage: add_note <note>")
		return "", nil
	}
	message = strings.Join(args[1:], " ")
	return message, nil
}

func main() {
	var args = os.Args
	if len(args) < 2 {
		fmt.Println("Usage: go run ./src [command]... [options]")
		os.Exit(1)
	}

	switch args[1] {
	case "add":
		noteMessage, err := AddNoteArgumentParser(args[2:len(args)])
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing add arguments: %v\n", err)
			os.Exit(1)
		}
