		if err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing search arguments: %v\n", err)
			os.Exit(1)
		}
		matchedNotes, _ := jsonstorage.LoadNotes()
		filters, err := parseSearchArgs(searchQuery, matchedNotes)
		if filters == nil || err != nil {
			fmt.Printf("Failed to load notes. Error: %v\n", err)
			return
		}

		matchedFiltered := searchNoteByFilter(filters, matchedNotes)
		json.NewEncoder(os.Stdout).SetIndent("", "\t")
		err = json.NewEncoder(os.Stdout).Encode(matchedFiltered)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Failed to encode found notes: %v", err)
		}

	default:
		fmt.Println("Unknown command:", args[1])
	}
}

func parseSearchArgs(query string, notes []jsonstorage.Note) (map[string]*jsonstorage.FilterOption, error) {
	var filters = map[string]*jsonstorage.FilterOption{}
	for _, s := range strings.Split(strings.TrimPrefix(query, "--"), " ") {
		filters[strings.TrimSpace(s)] = newFilterOptions()
	}
	return filters, nil
}

func parseSearchArg(arg string, notes []jsonstorage.Note) (*jsonstorage.FilterOption, error) {
	var filter *jsonstorage.FilterOption

	if len(arg) <= 2 || strings.HasPrefix(arg, "--") { // Filter arg parsing
		for _, s := range strings.Split(strings.TrimPrefix(arg, "--"), " ") {
			filter, _ = parseSearchArg(s, notes)
		}
		return filter, nil
	}

	noteCount := countFilters(notes)

	switch noteCount {
	case 1:
		sFilter := new(jsonstorage.FilterOption)
		filters := strings.Fields(sFilter.FilterString)
		for _, f := range filters[2:] { // skip FilterString "Title:" and ":Body"
			if f == "" {
				continue
			}
			filter = &jsonstorage.FilterOption{
				Type:           strings.TrimSpace(filters[1]),
				Term:           strings.TrimSpace(f),
				MatchSubstrings: false,
			}
			for _, o := range filter.OperandTypes() { // e.g. "T:" or ":B"
				if contains(notes, sFilter.Title, noteCount) && strings.HasPrefix(f, "T:") {
					f = f[2:]
				} else if contains(notes, sFilter.Body, noteCount) && strings.HasPrefix(f, ":B") { // :B will match Body as well
					f = f[3:]
				}
			}

			if filter.Term != "" {
				filters := newFilters(sFilter.FilterString)
				switch filters.Type {
				case "T:":
					filter.Terms.Title = append(filter.Terms.Title, string(f))
				default: // :B
					filter.Terms.Body = append(filter.Terms.Body, string(f))
				}
			}

			return filter, nil
		}

