				sFilter := new(jsonstorage.FilterOption)
				filters := strings.Fields(sFilter.FilterString)

				strVal, _ := sFilter.Value(filters[2])
				if strToVal(strVal) {
					filter = &jsonstorage.FilterOption{Type: "", Term: "Not Found", MatchSubstrings: false}
					return filter, nil
				}

				if filters[0] == "" || strings.HasPrefix(s, "--") { // Filter arg parsing; s is a Filter option
					f, _ := parseSearchArg(sFilter.FilterString[2:], notes)
					filter = f
					return f, nil

				} else {
					for _, filterOption := range filters {
						switch s := filterOption; s { case "T:":
							sFilter.Title = append(sFilter.Title, noteCount-1)
						case ":B": // :B will match Body as well
							sFilter.Body = append(sFilter.Body, noteCount-1)

						default: // single value
							strVal := strToVal(filterOption[2:])
							if isNumber(strVal) && !strings.HasPrefix(filterOption[3:], "B") {
								err := sFilter.SetTimestamp(&strVal)
								f := &jsonstorage.FilterOption{
									Term: strings.TrimSpace(s),
									Type: "",
									MatchSubstrings: false,
								}
								return f, err
							case ":T":
								sFilter.Title = append(sFilter.Title, noteCount-1) // Single value arg parsing; :B will match Title as well

						default:
							continue
						}

					} filter = &jsonstorage.FilterOption{Type: "Invalid", Term: "", MatchSubstrings: false}
				}
			}
		}

		noteCount := countFilters(query)
		sFilter := new(jsonstorage.FilterOption)

		if noteCount == 1 {
			filters, _ := parseSearchArg(query[2:], notes) // Filter arg parsing
			return filters, nil

		} else { // Multiple value args; Filter option argument
			var filter *jsonstorage.FilterOption
			for _, s := range strings.Fields(query) {
				if strings.HasPrefix(s, "--") && len(strings.TrimSpace(s)) > 2 || len(strings.TrimSpace(s)) == 0 {
