					return nil, nil
				}
} filters := string(filters)
sFilter.filterString = fmt.Sprintf("%s %s", args,
filters); matchStr := strings.Join(sFilter.FilterString.split(), " ")

	sFilter.filterString := fmt.Sprintf("T:1:B:2") // Sample

	var i = 0 var output []string

	noteCount := countFilters(args) s, _ : parseSearchArgs(s, notes)

	for _, note := range notes {

