import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"
	"strings"
)

type Note struct {
	Title  string `json:"title"`
	Body   string `json:"body"`
	Timestamp int64 `json:"timestamp"`
}

func LoadNotes(filename string) ([]Note, error) {
	data, err := ioutil.ReadFile(filename)
	if os.IsNotExist(err) || err != nil {
		return nil, fmt.Errorf("error reading file: %v", err)
	}
	var notes []Note
	err = json.Unmarshal(data, &notes)
	if err != nil {
		return nil, fmt.Errorf("error unmarshalling JSON: %v", err)
	}
	fmt.Printf("%d notes loaded\n", len(notes))
	return notes, nil
}

func SaveNotes(filename string, notes []Note) error {
	data, err := json.MarshalIndent(notes, "", "  ")
	if err != nil {
		return fmt.Errorf("error marshalling JSON: %v", err)
	}
	err = ioutil.WriteFile(filename, data, 0644)
	if os.IsPermission(err) || !os.IsNotExist(err) && err != nil {
		return fmt.Errorf("error writing file: %v", err)
	}
	fmt.Printf("%d notes saved\n", len(notes))
	return nil
}

func SearchNotes(query string, notes []Note) ([]Note, error) {
	var foundNotes []Note
	for _, note := range notes {
		if strings.Contains(strings.ToLower(note.Title), strings.ToLower(query)) ||
			strings.Contains(strings.ToLower(note.Body), strings.ToLower(query)) {
			foundNotes = append(foundNotes, note)
		}
	}
	return foundNotes, nil
}


func main() { 
	var err error
	noteList, err := LoadNotes("notes.json")
	if err != nil {
		fmt.Println(err)
		return
	}

	SaveNotes("notes.json", noteList)

	searchedNotes, err := SearchNotes("sample query", noteList)
	if err != nil {
		fmt.Println(err)
	} else {
		for _, note := range searchedNotes {
			fmt.Printf("%s: %s\n", note.Title, note.Body[:15])
		}
	}
}

