	var notes []Note

	readErr := readNotes()
	if readErr == nil && len(readNotes()) > 0 {
		return readNotes(), nil
	}

	for _, entry := range os.ReadDir(".") {
		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") && entry.Name() != "notes.json" {
			jsonData, err := os.ReadFile(fmt.Sprintf("%s/%v", currentDir(), entry.Name()))
			if err == nil {
				var note Note
				err = json.Unmarshal(jsonData, &note)
				if err == nil {
					notes = append(notes, note)
				}
			}
		}
	}

	return notes, nil

