package types

import (
	"time"
)

type Note string // A simple string type to represent a note

type AddCommand struct {
	Title   string `json:"title"`  // Title of the note
	Content Note    `json:"content"` // Content of the note
	Tags []string     `json:"tags,omitempty"` // Tags for searching and organizing notes (optional)
}

