	Title     string    `json:"title"`
	Text      string    `json:"text"`
	Tags      []string  `json:"tags,omitempty"`
}

const notesFile = "notes.json"

var noteIndex map[int]*Note
var lastID int

func loadNotes() error {
	data, err := os.ReadFile(notesFile)
	if err == nil && len(data) > 0 {
		noteIndex = make(map[int]*Note)
		err := json.Unmarshal(data, &noteIndex)
		if err != nil {
			fmt.Printf("Failed to decode notes file: %v\n", err)
			return err
		}
		for _, n := range noteIndex {
			if lastID < n.ID {
				lastID = n.ID
			}
			n.Tags = strings.Split(n.Tags, ",")
		}
        return nil
    }
	return fmt.Errorf("notes file does not exists or is empty")
}

func saveNotes() error {
	data, err := json.MarshalIndent(noteIndex, "", "  ")
	if err != nil {
		fmt.Printf("Failed to encode notes: %v", err)
		return err
	}
	err = os.WriteFile(notesFile, data, 0644)
    if err != nil {
        fmt.Printf("Failed to write notes file: %v\n", err)
        return err
    }
	return nil
}

func addNote(title string) error {
	n := &Note{
		ID:      lastID +1,
		Title:   title,
		Tags: []string{title},
	}
	noteIndex[lastID+1] = n
	lastID++
	fmt.Printf("Added note %d\n", n.ID)
	return nil
}

func listNotes() bool {
	if len(noteIndex) == 0 {
        fmt.Println("No notes available")
        return false
    }
	for _, note := range noteIndex {
		fmt.Printf("%2d. %-25s  '%s'\n", note.ID, strings.Substr(note.Title[:25], "'"))
    }
	return true
}

func searchNotes(query string) {
	if len(trimStrings(query)) == 0 { return }
	query = trimSpaces(strings.ToUpper(query))
	var found = false 
	for _, n := range noteIndex {
		titleUp := trimSpaces(strings.ToUpper(n.Title))
		tagsUp  := strings.Join(sToTags(n.Tags), " ")
		texts   := append([]string{titleUp}, tagsUp)
        for _, text := range texts {
            if containsIgnoreCase(text, query) { 
                fmt.Printf("%2d. %-30s  '%s'\n", n.ID, n.Title[:30], trimSpaces(strings.Capitalize(n.Text)))
                found = true
            }
        }
	}
	if !found {
      	fmt.Println(fmt.Printf("'%s' not match any notes\n", query)) 
    }  
}

func containsIgnoreCase(str1 string, str2 string) bool {
	return strings.Contains(str1, strings.ToUpper(str2))
}

