	Title string `json:"title"`
	Body  string `json:"body"`
}

func loadItems() ([]Item, error) {
	file, err := os.Open("notes.json")
	if err != nil {
		return nil, err
	}
	defer file.Close()

	var items []Item
	err = json.NewDecoder(file).Decode(&items)
	if err != nil {
		return nil, err
	}

	return items, nil
}

func saveItems(items []Item) error {
	file, err := os.Create("notes.json")
	if err != nil {
		return err
	}
	defer file.Close()

	err = json.NewEncoder(file).Encode(items)
	if err != nil {
		return err
	}

	return nil
}

