	cmd := "add" // Example subcommand: the command passed to the Go program at runtime
	switch cmd {
	case "add":
		title := "Title of note"
		body := "Body of note"
		items, _ := loadItems()
		newItem := Item{ID: len(items) + 1, Title: title, Body: body}
		items = append(items, newItem)
		err := saveItems(items)
		if err != nil {
			fmt.Println("Error:", err)
			return
		}
		fmt.Printf("%s added\n", newItem.Title)
	case "list":
		items, _ := loadItems()
		for _, item := range items {
			fmt.Printf("[%d] %s: %s\n", item.ID, item.Title, item.Body)
		}
	default:
		fmt.Println("Unknown command:", cmd)
