from pathlib import Path
import argparse
import json

class Task:
    def __init__(self, description: str, priority: int):
        self.description = description
        self.priority = priority

def read_tasks(file_path: Path) -> List[Task]:
    if file_path.exists():
        with open(file_path, 'r') as f:
            data = json.load(f)
            tasks = [Task(**t) for t in data]
    else:
        tasks = []

    return tasks

def write_tasks(file_path: Path, tasks: List[Task]):
    task_dicts = [t.__dict__ for t in tasks]

    with open(file_path, 'w') as f:
        json.dump(task_dicts, f)

def main():
    parser = argparse.ArgumentParser(description='A CLI task manager.')

    subparsers = parser.add_subparsers(dest='command')

    add_parser = subparsers.add_parser('add', help='Add a new task.')
    add_parser.add_argument('--priority', type=int, default=1,
                            choices=[1, 2, 3], help="Priority level (optional)")

    remove_parser = subparsers.add_parser('remove', help='Remove an existing task.')
    remove_parser.add_argument("task_id", type=str, help='Task id to delete')

    list_parser = subparsers.add_parser('list', help='List all tasks.')

    args = parser.parse_args()

    if not hasattr(args, 'command'):
        print("Please specify a command: add, remove or list")
        return

    data_file = Path(Path.home(), '.tasks.json').resolve()

    task_manager_tasks = read_tasks(data_file)
    task_manager = TaskManager(task_manager_tasks)

