#!/usr/bin/env python3

import argparse
import json
import os

def parse_args():
    parser = argparse.ArgumentParser(description='Task Manager CLI')
    subparsers = parser.add_subparsers(dest='command', required=True)

    add_parser = subparsers.add_parser('add', help='Add a new task')
    add_parser.add_argument('description', type=str, help='Task description')

    list_parser = subparsers.add_parser('list', help='List all tasks')

    done_parser = subparsers.add_parser('done', help="Mark a task as done")
    done_parser.add_argument("task_id", type=int, help="Task ID to mark as done")

    remove_parser = subparsers.add_parser('remove', help="Remove a task")
    remove_parser.add_argument("task_id", type=int, help="Task ID to remove")

    return parser.parse_args()

def save_tasks(tasks):
    with open('tasks.json', 'w') as f:
        json.dump(tasks, f)

def load_tasks():
    if os.path.exists('tasks.json'):
        with open('tasks.json', 'r') as f:
            return json.load(f)
    return []

def add_task(description):
    tasks = load_tasks()
    task_id = max(t['id'] for t in tasks) + 1 if tasks else 1
    new_task = {'id': task_id, 'description': description}
    tasks.append(new_task)
    save_tasks(tasks)

def list_tasks():
    tasks = load_tasks()
    if not tasks:
        print("No tasks to display!")
    for task in sorted(tasks, key=lambda t: t['id']):
        status = "[Done]" if "done" in task else "[Pending]"
        print(f"{task.get('priority', 'Medium')}: {status} #{task['id']} {task['description']}")

def mark_task_done(task_id):
    tasks = load_tasks()
    for t in tasks:
        if t["id"] == task_id:
            t["done"] = True
            save_tasks(tasks)
            print(f"Task #{task_id} marked as done.")
            break
    else:
        print(f"Could not find task ID {task_id}")

def remove_task(task_id):
    tasks = load_tasks()
    for i, t in enumerate(tasks):
        if task.get('id') == int(task_list) and 'done' not in task:
            del tasks[i]
            save_tasks(tasks)
            print(f"Task {task['description']} removed.")
            break
    else:
        print("No matching pending tasks found.")

def process_input(args):
    try:
        if args.command == "add":
