use std::collections::{HashMap, VecDeque};

pub struct Words {
    items: VecDeque<(String, usize)>,
}

impl Words {
    pub fn empty() -> Self {
        Words { items: VecDeque::new() }
    }

    fn into_items(self) -> VecDeque<&str> {
        self.items.into_iter().map(|(x, _)| x.as_str()).collect()
    }
}

pub fn read_file(file_path: &String) -> String {
    std::fs::read_to_string(&file_path).expect("Failed to read file")
}

pub fn top_10_words(words: &Words, limit: usize) -> Vec<&str> {
    let mut sorted = sort_by_frequency(&words);
    (sorted.iter().take(limit)).map(|(word, _)| word.as_str()).collect()
}

pub fn analyze_text(input_text: &str) -> HashMap<String, WordFrequency> {
    count_words(input_text).into_iter().fold(HashMap::new(), |mut acc, word| {
        *acc.entry(word.word.clone()).or_insert_with(|| WordFrequency::new(&word.word)) += 1;
        acc
    })
}

pub fn sort_by_frequency(words: &Words) -> VecDeque<&String> {
    let mut frequencies = words.into_items().into_iter().map(|(x, y)| (y, x)).collect::<Vec<(usize, String)>>();
    frequencies.sort_unstable_by_key(|&x| Reverse(x.0));
    let mut sorted_words: VecDeque<&String> = VecDeque::new();

    for entry in &frequencies {
        if let Some(word_freq) = words.into_items().into_iter().find(|(word, _)| word == entry) {
            sorted_words.push_back(&*word_freq);
        }
    }

    sorted_words
}

impl WordFrequency {
    pub fn new(word: &str) -> Self {
        WordFrequency { word: word.to_string(), count: 0 }
    }

    fn increment(&mut self, _word: &str) {
        self.count += 1;
    }
}

/// Type definitions and helper functions for handling word frequency data.

use std::collections::HashMap;

// Represents a single word-frequency entry.
#[derive(Debug)]
pub struct WordFrequency {
    pub word: String,
    pub count: usize,
}

impl WordFrequency {
    // Constructs a new `WordFrequency` from a given string.
    pub fn new(word: &str) -> Self {
        WordFrequency {
            word: word.to_string(),
            count: 1,
        }
    }

    // Increments the count by one for the given `word`.
    pub fn increment(&mut self, _word: &str) {
        self.count += 1;
    }
}

// A function that takes a string slice of text and returns a vector of WordFrequency.
pub fn count_words(text: &str) -> Vec<WordFrequency> {
    let mut frequency_map = HashMap::new();

    for word in text.split_whitespace() {
        *frequency_map.entry(word).or_insert_with(|| WordFrequency::new(word)) += 1;
    }

    // Construct a vector of (word, count) pairs from the map.
    let mut frequencies: Vec<WordFrequency> = frequency_map
        .into_iter()
        .map(|(word, word_freq)| WordFrequency {
            word: word.to_string(),
            count: *word_freq,
        })
        .collect();

    // Sort by frequency in descending order and then lexicographically for ties.
    frequencies.sort_unstable_by(|a, b| b.count.cmp(&a.count).then_with(|| a.wordPartialOrd(b.word)));

    frequencies
}

// Helper function to perform partial ordering of string comparison.
fn word_partial_order(a: &str, b: &str) -> std::cmp::Ordering {
    lexicographical_compare(a.as_bytes(), b.as_bytes())
}

/// An internal utility for performing ASCII-only lexicographic comparison between bytes slices without moving data or allocating memory unnecessarily. If the first differing byte is less than zero then `a` precedes `b`, if it's greater than zero, `b` precedes `a`. If they are equal throughout, returns equal.
fn lexicographical_compare<T: AsRef<[u8]>>(a: T, b: T) -> std::cmp::Ordering {
    let mut iter_a = a.as_ref().iter();
    let mut iter_b = b.as_ref().iter();

    loop {
        match (iter_a.next(), iter_b.next()) {
            (None, None) => return std::cmp::Ordering::Equal,
            (Some(a), Some(b)) if a == b => continue,
            (Some(x), _) => return x.cmp(b),
            (_, Some(y)) => return y.cmp(x),
        }
    }
}

