            .chars()
            .flat_map(|c| c.to_lowercase().next())
            .collect::<String>()
    }).collect::<Vec<String>>();

    let mut counts = HashMap::new();
    for word in words {
        *counts.entry(word).or_insert(0) += 1;
    }

    let mut items: Vec<(String, usize)> = counts.into_iter(). collect();
    items.sort_by(|a, b| b.1.cmp(&a.1));
    items.truncate(10);

	items
}

