import { loadPlaylists, savePlaylists } from './storage';
interface Playlist {
  id: string;
  name: string;
  songs: string[];
}

export class PlaylistManager {
  private playlists: Playlist[] = [];

  constructor() {
    this.loadPlaylists();
  }

  private loadPlaylists() {
    this.playlists = loadPlaylists();
  }

  private savePlaylists() {
    savePlaylists(this.playlists);
  }

  create(name: string): Playlist {
    const playlist: Playlist = {
      id: Date.now().toString(),
      name,
      songs: [],
    };
    this.playlists.push(playlist);
    this.savePlaylists();
    return playlist;
  }

  delete(id: string): boolean {
    const index = this.playlists.findIndex(p => p.id === id);
    if (index === -1) return false;
    this.playlists.splice(index, 1);
    this.savePlaylists();
    return true;
  }

  addSong(playlistId: string, song: string): boolean {
    const playlist = this.playlists.find(p => p.id === playlistId);
    if (!playlist) return false;
    playlist.songs.push(song);
    this.savePlaylists();
    return true;
  }

  removeSong(playlistId: string, song: string): boolean {
    const playlist = this.playlists.find(p => p.id === playlistId);
    if (!playlist) return false;
    const index = playlist.songs.indexOf(song);
    if (index === -1) return false;
    playlist.songs.splice(index, 1);
    this.savePlaylists();
    return true;
  }
}

import { Playlist } from '../types/types.ts';

export async function loadPlaylists(): Promise<Playlist[]> {
  try {
    const response = await fetch('/data/playlists.json');
    if (!response.ok) {
      throw new Error(`Failed to load playlists: ${response.statusText}`);
    }
    return await response.json();
  } catch (error) {
    console.error('Error loading playlists:', error);
    return [];
  }
}

export async function savePlaylists(playlists: Playlist[]): Promise<void> {
  try {
    const response = await fetch('/data/playlists.json', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(playlists),
    });
    if (!response.ok) {
      throw new Error(`Failed to save playlists: ${response.statusText}`);
    }
  } catch (error) {
    console.error('Error saving playlists:', error);
  }
}

