import os
import hashlib

def calculate_md5(file_path):
    hash_md5 = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def find_duplicates(directory):
    files_by_size = {}
    file_hashes = {}

    # Traverse the directory and group files by size
    for root, _, files in os.walk(directory):
        for filename in files:
            full_path = os.path.join(root, filename)
            try:
                file_stat = os.lstat(full_path)
                file_size = str(file_stat.st_size)

                if file_size not in files_by_size:
                    files_by_size[file_size] = {}
                files_by_size[file_size][os.lstat(full_path).st_ino] = {
                    'path': full_path,
                    'hash': None
                }
            except OSError as e:
                print(f"Skipping {full_path}: {e}")

    # Calculate MD5 hash for the duplicate-sized files
    duplicates = []
    for size, inode_map in files_by_size.items():
        if len(inode_map) > 1:
            paths = list(inode_map.values())
            path_map = {}
            for file_info in paths:
                path = file_info['path']
                try:
                    with open(path, 'rb') as f:
                        hash_md5 = hashlib.md5()
                        for chunk in iter(lambda: f.read(4096), b""):
                            hash_md5.update(chunk)
                        file_hashes[path] = hash_md5.hexdigest()
                except OSError as e:
                    print(f"Skipping {path}: {e}")

            hash_count = {}
            for path, _hash in file_hashes.items():
                if _hash not in hash_count:
                    hash_count[_hash] = []
                hash_count[_hash].append(path)

            for group in hash_count.values():
                if len(group) > 1:
                    duplicates.extend([(group[i], group[j]) for i in range(len(group)) for j in range(i + 1, len(group))])

    return duplicates

def main():
    import argparse
    parser = argparse.ArgumentParser(description="Find duplicate files by content hash in a directory.")
    parser.add_argument("directory", help="Directory to search for duplicates")
    args = parser.parse_args()

    try:
        _duplicates = find_duplicates(args.directory)
        if _duplicates:
            print("\nDuplicate file pairs:")
            for pair in _duplicates:
                print(pair[0], '=>', pair[1])
        else:
            print("No duplicate files found.")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()

