    parser = argparse.ArgumentParser(description='Recursively scans a directory for duplicate files by content hash.')
    parser.add_argument('path', nargs='+', help='Path of the directory to scan')

    args = parser.parse_args()

    try:
        files = []
        for _ in args.path:
            files += open(_).readlines()

        duplicates = find_duplicates(files)

        if not duplicates:
            print(f'No duplicate groups found.')
        else:
            for i, group in enumerate(duplicates):
                print(f'Duplicate Group {i + 1}:')
                print('\n'.join(sorted(group)))
    except Exception as e:
        print(str(e), file=sys.stderr)

