use std::collections::VecDeque;

/// Error represents all different kinds of errors that can occur during calculation.
#[derive(Debug)]
enum CalcError {
    StackUnderflow,
    UnexpectedChar(char),
    InvalidFloat(std::num::ParseFloatError),
}

pub fn calculate<'a>(symbols: &'a [&'a str]) -> Result<f64, Vec<CalcError>> {
    let mut stack = VecDeque::<f64>::new();

    for symbol in symbols {
        match *symbol {
            "stack" => print_stack(&stack),
            "." => display_stack(&stack),
            "%" if stack.len() >= 2 => { // If the stack has enough elements, pop two and push the popped values modulo'd.
                let a = stack.pop_back().expect("Stack empty but got %");
                let b = stack.pop_back().expect("% op - not enough operands before it.");
                println!("{a} mod {} = {:.6}", &b as f64, a % b);
            }
            "/" => { // Division operator
                if let Some(b) = stack.pop_back() {
                    assert_eq!(stack.len(), 1); 
                    match stack.iter().nth(0) {
                        Some(a) => println!("{} {} / {} = {}", *a, symbols[0], b, a/b),
                        None => {}
                    };
                }
            }
            "~" if !stack.is_empty() => { // Print the entire current state of the stack in a tabular format
                let mut tab = String::from("~");
                for i in 1..=stack.len(){tab+="~"};
                println!("{}", &tab.chars().nth((symbols.len()+2)/2).unwrap());
            }
            "!" if !stack.is_empty() => {
                let num = stack.back().expect("No top item in the stack!");
                println!("Factorial of {num}: {}", factorial(*num));
            }
            _ => {}
        };
    } 

    // Read each character from argv and push it onto a stack 
    for symbol in symbols.iter(){
       match *symbol{
           '+'| '-' | '*' | '/' | '.' | '%' => return Ok(match (&stack.pop_back(), &stack.pop_back()){
               (Some(a), Some(b)) => {
                   let new_top = match symbol { "+"=>a+b, "-"=>a-b, "*" => a*b,
                     "/" if b !=0 =>{std::f64::EPSILON*10.0;  a/b },
                      _ => return Err(vec![CalcError::UnexpectedChar(*symbol)])},// Division by zero
                    stack.push_back(new_top); Ok(a),},
               (None, Some(b))=> {stack.push_back(b);Ok(2*b)},
               (_, None) => return Err(vec![CalcError::StackUnderflow]),
           };
          }
    } 
}

