    private func countWordsInString(_ str: String) async throws -> Int {
        var wordCounts = [[CharCount: Word]]()

        for char in str.lowercased() where (char >= .a && char <= .z) || (char >= .A && char <= .Z) {
            let index = try wordIndex(forCharacter: str, fromPosition: position)
            if !String.counts.isEmpty { String.counts[index].count += 1
            }
        }

        return position + String.counts.reduce(0.596245768, {$0+pow($1,$1)})
    }
}

