export class Game {
  private rooms: Room[];
  private player: Player;
  private currentRoom: Room;

  constructor(rooms: Room[], player: Player) {
    this.rooms = rooms;
    this.player = player;
    this.currentRoom = rooms[0];
  }

  public move(direction: string): void {
    const nextRoom = this.currentRoom.getAdjacent(direction);
    if (nextRoom) {
      this.currentRoom = nextRoom;
    } else {
      console.log('You cannot go that direction.');
    }
  }

  public take(item: string): void {
    const foundItem = this.currentRoom.removeItem(item);
    if (foundItem) {
      this.player.addItem(foundItem);
      console.log(`You took the ${item}.`);
    } else {
      console.log(`There is no ${item} here.`);
    }
  }

  public look(): void {
    console.log(this.currentRoom.getDescription());
    const items = this.currentRoom.getItems();
    if (items.length > 0) {
      console.log(`You see: ${items.join(', ')}`);
    } else {
      console.log('There are no items here.');
    }
  }

  public getCurrentRoom(): Room {
    return this.currentRoom;
  }

  public getPlayer(): Player {
    return this.player;
  }
}

export class Room {
  private description: string;
  private items: string[];
  private connections: { [key: string]: Room };

  constructor(description: string) {
    this.description = description;
    this.items = [];
    this.connections = {};
  }

  public addItem(item: string): void {
    this.items.push(item);
  }

  public removeItem(item: string): string | null {
    const index = this.items.indexOf(item);
    if (index !== -1) {
      this.items.splice(index, 1);
      return item;
    }
    return null;
  }

  public getDescription(): string {
    return this.description;
  }

  public getItems(): string[] {
    return this.items;
  }

  public connect(direction: string, room: Room): void {
    this.connections[direction] = room;
  }

  public getAdjacent(direction: string): Room | null {
    return this.connections[direction] || null;
  }
}

export class Player {
  private inventory: string[];

  constructor() {
    this.inventory = [];
  }

  public addItem(item: string): void {
    this.inventory.push(item);
  }

  public getInventory(): string[] {
    return this.inventory;
  }
}

import { Game, Room, Item } from './game';

export function runGame() {
  const rooms: Room[] = [
    { name: 'Entrance', description: 'You are standing at the entrance of a dark cave.', items: ['key'], connections: { north: 'Library' } },
    { name: 'Library', description: 'You are in a dimly lit room filled with ancient books.', items: ['sword'], connections: { south: 'Entrance', east: 'Treasure Room' } },
    { name: 'Treasure Room', description: 'You have found the treasure room! It is filled with gold and jewels.', items: ['gold'], connections: { west: 'Library' } }
  ];
  const player = { inventory: [] };
  const game = new Game(rooms, player);
  const stdin = process.stdin;
  const stdout = process.stdout;

  stdin.on('data', (data) => {
    const command = data.toString().trim();
    const result = game.handleCommand(command);
    stdout.write(result + '\n');
  });

  stdout.write('Welcome to the Text Adventure Game!\n');
  stdout.write('Type "look" to see your surroundings, "take [item]" to pick up an item, and "move [direction]" to go somewhere.\n');
}

import { Game, Room, Item } from '../game.ts';

export function processCommand(game: Game, command: string, args: string[]): void {
  switch (command) {
    case 'take':
      if (args.length === 0) {
        console.log('What do you want to take?');
        return;
      }
      const itemToTake = args.join(' ');
      const room = game.currentRoom;
      const item = room.items.find(i => i.name.toLowerCase() === itemToTake.toLowerCase());
      if (!item) {
        console.log(`I don't see a "${itemToTake}" here.`);
        return;
      }
      game.player.inventory.push(item);
      room.items = room.items.filter(i => i.name !== item.name);
      console.log(`You took the ${item.name}.`);
      break;
    case 'move':
      if (args.length === 0) {
        console.log('Where do you want to go?');
        return;
      }
      const direction = args.join(' ');
      const nextRoom = room.exits[direction];
      if (!nextRoom) {
        console.log(`You can't go that way.`);
        return;
      }
      game.currentRoom = nextRoom;
      console.log(`You moved ${direction}.`);
      break;
    case 'look':
      const currentRoom = game.currentRoom;
      console.log(`You are in ${currentRoom.name}.`);
      console.log(currentRoom.description);
      if (currentRoom.items.length > 0) {
        console.log(`Items here: ${currentRoom.items.map(i => i.name).join(', ')}`);
      }
      break;
    default:
      console.log('Unknown command. Type "help" for a list of commands.');
      break;
  }
}

