      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(todos),
    });
    if (!response.ok) {
      throw new Error(`Failed to save todos: ${response.statusText}`);
    }
  } catch (error) {
    console.error('Failed to save todos:', error);
  }
}

