import * as fs from 'fs';
import * as path from 'path';
import { createHash } from 'crypto';

export function walkDirectoryAndHashFiles(directory) {
  const result = {};
  const walkSync = (dirPath) => {
    for (const dirent of fs.readdirSync(dirPath, { withFileTypes: true })) {
      if (dirent.isDirectory()) {
        walkSync(path.join(dirPath, dirent.name));
      } else {
        const filePath = path.join(dirPath, dirent.name);
        try {
          const fileHash = createHash('sha256');
          fileHash.update(fs.readFileSync(filePath));
          result[fileHash.digest('hex')] || [];
          result[fileHash.digest('hex')].push({ size: fs.statSync(filePath).size, path: filePath });
        } catch (e) { continue; }
      }
    }
  };
  walkSync(directory);
  return result;
}

