const fs = require('fs');
const path = './notes.json';

export function loadNotes() {
  try { return JSON.parse(fs.readFileSync(path, 'utf-8')) || []; } catch { return []; }
}

export function saveNote(note) {
  note.id = crypto.randomBytes(16).toString('hex');
  fs.writeFileSync(path, JSON.stringify([...loadNotes(), note]));
}

export function deleteNote(id) {
  const notes = loadNotes(); notes.splice(notes.findIndex(n => n.id === id), 1);
  fs.writeFileSync(path, JSON.stringify(notes));
}

